 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        cells.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    guides = []
    for color, cells in comps:
        rows = {r for r, _ in cells}
        cols = {c for _, c in cells}
        for cr in rows:
            for cc in cols:
                horizontal = {c for r, c in cells if r == cr}
                vertical = {r for r, c in cells if c == cc}
                if (len(horizontal) >= 3 and len(vertical) >= 3 and
                        len(cells) == len(horizontal) + len(vertical) - 1 and
                        all(r == cr or c == cc for r, c in cells)):
                    guides.append((len(cells), color, cells, cr, cc,
                                   min(horizontal), max(horizontal),
                                   min(vertical), max(vertical)))
    if not guides:
        return [row[:] for row in grid]
    _, guide_color, guide, cr, cc, cmin, cmax, rmin, rmax = max(guides, key=lambda x: x[0])

    # The L's open diagonal is opposite its two arms. Recolor the largest
    # non-background object wholly in that quadrant to the L's color.
    row_sign = -1 if rmin == cr else 1
    col_sign = -1 if cmin == cc else 1
    candidates = []
    for color, cells in comps:
        if cells == guide:
            continue
        if all((r - cr) * row_sign > 0 and (c - cc) * col_sign > 0
               for r, c in cells):
            candidates.append((len(cells), cells))
    if not candidates:
        return [row[:] for row in grid]
    target = max(candidates, key=lambda x: x[0])[1]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide_color
    return out


